import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';

// Quaternius CC0 CommonTree_5 static geometry buffer; inventory and source hashes in docs/resources.
const TREE_DATA = '';

/** Interpretive planting and furniture, not surveyed campus features.
 * All solid props are admitted by the caller's route/footprint test and have
 * matching collision meshes before the player's collision tree is baked. */
export function createHuyuCourtyards(
  isClear: (x: number, z: number, radius: number) => boolean,
): { visual: THREE.Group; colliders: THREE.Group; dispose: () => void } {
  const world = new THREE.Group();
  const colliders = new THREE.Group();
  let disposed = false;
  world.name = 'huyu-pocket-gardens';
  world.userData.treeTextureStatus = 'not-needed';
  const beds: [number, number][] = [
    [0, -182], [29, -182], [-91, -12], [-60, -12], [57, -53], [79, -53],
  ];
  const benches: [number, number, number][] = [
    [1, -177, 0], [28, -177, 0], [-90, -9, 0], [-60, -9, 0], [57, -40, 0], [79, -50, 0],
  ];
  const foliage = new THREE.MeshStandardMaterial({ color: 0x829d79, roughness: 1 });
  const flower = new THREE.MeshStandardMaterial({ color: 0xd9c8bc, roughness: 1 });
  const stone = new THREE.MeshStandardMaterial({ color: 0xd9d2c0, roughness: 1 });
  const soil = new THREE.MeshStandardMaterial({ color: 0x786e5b, roughness: 1 });
  const wood = new THREE.MeshStandardMaterial({ color: 0x956e49, roughness: 1 });
  const metal = new THREE.MeshStandardMaterial({ color: 0x405e57, roughness: 1 });
  const proxyMaterial = new THREE.MeshBasicMaterial();
  const box = new THREE.BoxGeometry(1, 1, 1);
  const mound = new THREE.SphereGeometry(1, 8, 6);
  const batches = new Map<THREE.Material, THREE.BufferGeometry[]>();
  const batch = (mesh: THREE.Mesh): void => {
    mesh.updateMatrix();
    const geometries = batches.get(mesh.material as THREE.Material) ?? [];
    geometries.push(mesh.geometry.clone().applyMatrix4(mesh.matrix));
    batches.set(mesh.material as THREE.Material, geometries);
  };
  const addBox = (parent: THREE.Group, mat: THREE.Material, x: number, y: number, z: number, sx: number, sy: number, sz: number, angle = 0): void => {
    const m = new THREE.Mesh(parent === colliders ? new THREE.BoxGeometry(1, 1, 1) : box, mat); m.position.set(x, y, z); m.scale.set(sx, sy, sz); m.rotation.y = angle;
    m.castShadow = m.receiveShadow = true; if (parent === colliders) parent.add(m); else batch(m);
  };
  // Ankle-height beds and groundcover are intentionally traversable, like
  // the existing low planters. Clearance still keeps them off routes/buildings.
  for (const [x, z] of beds) {
    if (!isClear(x, z, 2.1)) continue;
    addBox(world, stone, x, .11, z, 3.5, .18, 1.45);
    addBox(world, soil, x, .22, z, 3.2, .04, 1.2);
    for (let i = 0; i < 9; i++) {
      const plant = new THREE.Mesh(mound, i % 4 === 0 ? flower : foliage);
      plant.position.set(x - 1.25 + (i % 5) * .62, i % 4 === 0 ? .38 : .33, z + (i < 5 ? -.25 : .25));
      plant.scale.set(i % 4 === 0 ? .16 : .31, i % 4 === 0 ? .11 : .17, i % 4 === 0 ? .16 : .29);
      plant.castShadow = true; batch(plant);
    }
  }
  for (const [x, z, angle] of benches) {
    if (!isClear(x, z, 1.8)) continue;
    const place = (mat: THREE.Material, lx: number, y: number, lz: number, sx: number, sy: number, sz: number): void => {
      addBox(world, mat, x + lx * Math.cos(angle) + lz * Math.sin(angle), y, z - lx * Math.sin(angle) + lz * Math.cos(angle), sx, sy, sz, angle);
    };
    // Reuses the project's established warm wood / teal metal bench language.
    for (let i = 0; i < 3; i++) place(wood, 0, .51, -.18 + i * .18, 1.9, .08, .14);
    for (let i = 0; i < 2; i++) place(wood, 0, .76 + i * .17, -.27, 1.9, .13, .08);
    place(metal, -.7, .25, 0, .12, .5, .48); place(metal, .7, .25, 0, .12, .5, .48);
    addBox(colliders, proxyMaterial, x, .49, z, 1.9, .98, .58, angle);
  }
  // Original CC0 tree mesh is synchronous; only its leaf texture is loaded
  // asynchronously. A visible fallback crown and physical trunk exist first.
  const treeSites: [number, number][] = [[-5, -188], [-95, -14], [78, -57]];
  const acceptedTrees = treeSites.filter(([x, z]) => isClear(x, z, 3.5));
  world.userData.treeCount = acceptedTrees.length;
  if (acceptedTrees.length) {
    const raw = Uint8Array.from(atob(TREE_DATA), c => c.charCodeAt(0)).buffer;
    const meshGeometry = (p: number, n: number, uv: number, idx: number, vertices: number, indices: number): THREE.BufferGeometry => {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(raw.slice(p, p + vertices * 12)), 3));
      geo.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(raw.slice(n, n + vertices * 12)), 3));
      geo.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(raw.slice(uv, uv + vertices * 8)), 2));
      geo.setIndex(new THREE.BufferAttribute(new Uint16Array(raw.slice(idx, idx + indices * 2)), 1));
      return geo;
    };
    const barkGeometry = meshGeometry(36368, 63644, 90920, 109104, 2273, 5646);
    const leafGeometry = meshGeometry(161996, 193196, 224396, 245196, 2600, 3900);
    const barkMaterial = new THREE.MeshStandardMaterial({ color: 0x806c55, roughness: 1 });
    const leafMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, side: THREE.DoubleSide, alphaTest: .2 });
    const trunk = new THREE.InstancedMesh(barkGeometry, barkMaterial, acceptedTrees.length);
    const leaves = new THREE.InstancedMesh(leafGeometry, leafMaterial, acceptedTrees.length);
    const fallback = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), foliage, acceptedTrees.length);
    const matrix = new THREE.Object3D();
    acceptedTrees.forEach(([x, z], i) => {
      matrix.position.set(x, 0, z); matrix.scale.setScalar(1); matrix.updateMatrix(); trunk.setMatrixAt(i, matrix.matrix); leaves.setMatrixAt(i, matrix.matrix);
      matrix.position.set(x, 4.5, z); matrix.scale.set(1.7, 2, 1.7); matrix.updateMatrix(); fallback.setMatrixAt(i, matrix.matrix);
      const proxy = new THREE.Mesh(new THREE.CylinderGeometry(.55, .55, 3, 8), proxyMaterial);
      proxy.position.set(x, 1.5, z); colliders.add(proxy);
    });
    for (const mesh of [trunk, leaves, fallback]) { mesh.instanceMatrix.needsUpdate = true; mesh.computeBoundingSphere(); mesh.castShadow = mesh.receiveShadow = true; world.add(mesh); }
    leaves.visible = false;
    world.userData.treeTextureStatus = 'loading';
    new THREE.TextureLoader().load(`${import.meta.env.BASE_URL}assets/environment/Leaves_NormalTree_C.png`, texture => {
      if (disposed) { texture.dispose(); return; }
      texture.colorSpace = THREE.SRGBColorSpace; texture.flipY = false; leafMaterial.map = texture; leafMaterial.needsUpdate = true;
      leaves.visible = true; fallback.visible = false; world.userData.treeTextureStatus = 'ready';
    }, undefined, () => { if (!disposed) world.userData.treeTextureStatus = 'fallback'; });
  }
  for (const [mat, geometries] of batches) {
    const merged = mergeGeometries(geometries);
    geometries.forEach(g => g.dispose());
    if (merged) { const mesh = new THREE.Mesh(merged, mat); mesh.castShadow = mesh.receiveShadow = true; world.add(mesh); }
  }
  for (const mat of [foliage, flower, stone, soil, wood, metal]) if (!batches.has(mat) && !(mat === foliage && acceptedTrees.length)) mat.dispose();
  if (!colliders.children.length) proxyMaterial.dispose();
  box.dispose(); mound.dispose();
  return { visual: world, colliders, dispose: () => { disposed = true; world.userData.treeTextureStatus = 'disposed'; } };
}
